for (const [key, value] of Object.entries(translations)) {
    if (key.length > 44) {
        const slice = key.replace(/\s+/g, ' ').slice(0, 43).trimEnd();
        const last = slice.lastIndexOf(' ');
        const compact = (last >= 26 ? slice.slice(0, last) : slice) + '…';
        translations[compact] = value.length > 44 ? value.slice(0, 40).trimEnd() + '…' : value;
    }
}
